package io.github.ningpp.compat;

/** Replacement for System.Runtime.InteropServices.MemoryMarshal (generated by CSharpToJava converter). */
public class MemoryMarshal {
    public static ReadOnlySpan<Integer> asBytes(ReadOnlySpan<Integer> span) {
        int len = span.length();
        Integer[] bytes = new Integer[len * 4];
        for (int i = 0; i < len; i++) {
            int cp = span.get(i);
            bytes[i * 4] = (cp >>> 24) & 0xFF;
            bytes[i * 4 + 1] = (cp >>> 16) & 0xFF;
            bytes[i * 4 + 2] = (cp >>> 8) & 0xFF;
            bytes[i * 4 + 3] = cp & 0xFF;
        }
        return new ReadOnlySpan<>(bytes);
    }
}
